class Solution:
    def maxSlidingWindow(self, nums, k):
        from collections import deque
        d = deque(); out = []
        for i, x in enumerate(nums):
            while d and nums[d[-1]] <= x: d.pop()
            d.append(i)
            if d[0] <= i - k: d.popleft()
            if i >= k - 1: out.append(nums[d[0]])
        return out

