class Solution:
    def combinationSum(self, candidates, target):
        candidates = sorted(candidates)
        out, path = [], []
        def go(start, left):
            if left == 0:
                out.append(path[:])
                return
            for i in range(start, len(candidates)):
                if candidates[i] > left:
                    break
                path.append(candidates[i])
                go(i, left - candidates[i])
                path.pop()
        go(0, target)
        return out

