class Solution:
    def cloneGraph(self, node):
        if node is None:
            return None
        copies = {node: Node(node.val)}
        stack = [node]
        while stack:
            n = stack.pop()
            for m in n.neighbors:
                if m not in copies:
                    copies[m] = Node(m.val)
                    stack.append(m)
                copies[n].neighbors.append(copies[m])
        return copies[node]

class Solution:
    def canFinish(self, numCourses, prerequisites):
        graph = [[] for _ in range(numCourses)]
        indeg = [0] * numCourses
        for a, b in prerequisites:
            graph[b].append(a)
            indeg[a] += 1
        queue = [i for i in range(numCourses) if indeg[i] == 0]
        for c in queue:
            for d in graph[c]:
                indeg[d] -= 1
                if indeg[d] == 0:
                    queue.append(d)
        return len(queue) == numCourses

class Solution:
    def pacificAtlantic(self, heights):
        m, n = len(heights), len(heights[0])
        def flood(starts):
            seen = set(starts)
            stack = list(starts)
            while stack:
                r, c = stack.pop()
                for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < m and 0 <= nc < n and (nr, nc) not in seen and heights[nr][nc] >= heights[r][c]:
                        seen.add((nr, nc))
                        stack.append((nr, nc))
            return seen
        pac = flood([(0, c) for c in range(n)] + [(r, 0) for r in range(m)])
        atl = flood([(m - 1, c) for c in range(n)] + [(r, n - 1) for r in range(m)])
        return [[r, c] for r, c in sorted(pac & atl)]

