class Solution:
    def alienOrder(self, words):
        graph = {c: set() for w in words for c in w}
        indeg = {c: 0 for c in graph}
        for a, b in zip(words, words[1:]):
            for x, y in zip(a, b):
                if x != y:
                    if y not in graph[x]:
                        graph[x].add(y)
                        indeg[y] += 1
                    break
            else:
                if len(a) > len(b):
                    return ""
        queue = sorted(c for c in indeg if indeg[c] == 0)
        out = []
        while queue:
            c = queue.pop(0)
            out.append(c)
            for d in sorted(graph[c]):
                indeg[d] -= 1
                if indeg[d] == 0:
                    queue.append(d)
        return "".join(out) if len(out) == len(graph) else ""

