class Solution:
    def mergeKLists(self, lists):
        heap = [(h.val, i, h) for i, h in enumerate(lists) if h]
        heapify(heap)
        dummy = tail = ListNode()
        while heap:
            _, i, node = heappop(heap)
            tail.next = tail = node
            if node.next:
                heappush(heap, (node.next.val, i, node.next))
        return dummy.next

