class Solution:
    def exist(self, board, word):
        m, n = len(board), len(board[0])
        if Counter(word) - Counter(c for r in board for c in r):
            return False
        def go(r, c, i):
            if i == len(word):
                return True
            if not (0 <= r < m and 0 <= c < n) or board[r][c] != word[i]:
                return False
            board[r][c] = "#"
            found = go(r + 1, c, i + 1) or go(r - 1, c, i + 1) or go(r, c + 1, i + 1) or go(r, c - 1, i + 1)
            board[r][c] = word[i]
            return found
        return any(go(r, c, 0) for r in range(m) for c in range(n))

class Solution:
    def characterReplacement(self, s, k):
        count = Counter()
        best = top = left = 0
        for right, c in enumerate(s):
            count[c] += 1
            top = max(top, count[c])
            while right - left + 1 - top > k:
                count[s[left]] -= 1
                left += 1
            best = max(best, right - left + 1)
        return best

