class Solution:
    def isSameTree(self, p, q):
        if not p or not q:
            return p is q
        return p.val == q.val and self.isSameTree(p.left, q.left) and self.isSameTree(p.right, q.right)

class Solution:
    def invertTree(self, root):
        stack = [root]
        while stack:
            n = stack.pop()
            if n:
                n.left, n.right = n.right, n.left
                stack += [n.left, n.right]
        return root

class Solution:
    def maxPathSum(self, root):
        order, stack = [], [root]
        while stack:
            n = stack.pop()
            order.append(n)
            stack += [c for c in (n.left, n.right) if c]
        gain, best = {None: 0}, root.val
        for n in reversed(order):
            l, r = max(gain[n.left], 0), max(gain[n.right], 0)
            best = max(best, n.val + l + r)
            gain[n] = n.val + max(l, r)
        return best

class Solution:
    def levelOrder(self, root):
        out, level = [], [root] if root else []
        while level:
            out.append([n.val for n in level])
            level = [c for n in level for c in (n.left, n.right) if c]
        return out

class Codec:
    def serialize(self, root):
        out, stack = [], [root]
        while stack:
            n = stack.pop()
            if n is None:
                out.append("#")
            else:
                out.append(str(n.val))
                stack += [n.right, n.left]
        return ",".join(out)

    def deserialize(self, data):
        vals = iter(data.split(","))
        def build():
            v = next(vals)
            if v == "#":
                return None
            n = TreeNode(int(v))
            n.left = build()
            n.right = build()
            return n
        return build()

class Solution:
    def isSubtree(self, root, subRoot):
        def ser(n):
            out, stack = [], [n]
            while stack:
                x = stack.pop()
                if x is None:
                    out.append("#")
                else:
                    out.append("^" + str(x.val))
                    stack += [x.right, x.left]
            return "," + ",".join(out) + ","
        return ser(subRoot) in ser(root)

