class Solution:
    def buildTree(self, preorder, inorder):
        where = {v: i for i, v in enumerate(inorder)}
        it = iter(preorder)
        def build(lo, hi):
            if lo > hi:
                return None
            v = next(it)
            n = TreeNode(v)
            n.left = build(lo, where[v] - 1)
            n.right = build(where[v] + 1, hi)
            return n
        return build(0, len(inorder) - 1)

class Solution:
    def isValidBST(self, root):
        stack, prev, n = [], None, root
        while stack or n:
            while n:
                stack.append(n)
                n = n.left
            n = stack.pop()
            if prev is not None and n.val <= prev:
                return False
            prev, n = n.val, n.right
        return True

class Solution:
    def kthSmallest(self, root, k):
        stack, n = [], root
        while True:
            while n:
                stack.append(n)
                n = n.left
            n = stack.pop()
            k -= 1
            if k == 0:
                return n.val
            n = n.right

