class Solution:
    def lowestCommonAncestor(self, root, p, q):
        n = root
        while True:
            if p < n.val and q < n.val:
                n = n.left
            elif p > n.val and q > n.val:
                n = n.right
            else:
                return n.val

class Trie:
    def __init__(self):
        self.root = {}

    def insert(self, word):
        n = self.root
        for c in word:
            n = n.setdefault(c, {})
        n["$"] = True

    def _walk(self, s):
        n = self.root
        for c in s:
            if c not in n:
                return None
            n = n[c]
        return n

    def search(self, word):
        n = self._walk(word)
        return n is not None and "$" in n

    def startsWith(self, prefix):
        return self._walk(prefix) is not None

class WordDictionary:
    def __init__(self):
        self.root = {}

    def addWord(self, word):
        n = self.root
        for c in word:
            n = n.setdefault(c, {})
        n["$"] = True

    def search(self, word):
        level = [self.root]
        for c in word:
            if c == ".":
                level = [child for n in level for k, child in n.items() if k != "$"]
            else:
                level = [n[c] for n in level if c in n]
            if not level:
                return False
        return any("$" in n for n in level)

