class Solution:
    def findWords(self, board, words):
        trie = {}
        for w in words:
            n = trie
            for c in w:
                n = n.setdefault(c, {})
            n["$"] = w
        m, k = len(board), len(board[0])
        found = []
        def go(r, c, parent):
            ch = board[r][c]
            node = parent[ch]
            if "$" in node:
                found.append(node.pop("$"))
            board[r][c] = "#"
            for a, b in ((r + 1, c), (r - 1, c), (r, c + 1), (r, c - 1)):
                if 0 <= a < m and 0 <= b < k and board[a][b] in node:
                    go(a, b, node)
            board[r][c] = ch
            if not node:
                parent.pop(ch)
        for r in range(m):
            for c in range(k):
                if board[r][c] in trie:
                    go(r, c, trie)
        return found

